INSERT INTO beer_styles (name, category, description, og_min, og_max, fg_min, fg_max, abv_min, abv_max, ibu_min, ibu_max, srm_min, srm_max, is_bjcp)
VALUES
  ('American Light Lager', 'Standard American Beer', 'A highly carbonated, very light-bodied, nearly flavorless lager designed to be consumed very cold. Very refreshing and thirst-quenching.', 1.028, 1.04, 0.998, 1.008, 2.8, 4.2, 8, 12, 2, 3, true),
  ('American Lager', 'Standard American Beer', 'A very pale, highly-carbonated, light-bodied, well-attenuated lager with a very neutral flavor profile and low bitterness. Served very cold, it can be a very refreshing and thirst-quenching drink.', 1.04, 1.05, 1.004, 1.01, 4.2, 5.3, 8, 18, 2, 3.5, true),
  ('Cream Ale', 'Standard American Beer', 'A clean, well-attenuated, highly carbonated, flavorful American “lawnmower” beer. Easily drinkable, smooth, and refreshing, with more character than typical American lagers, yet still subtle and restrained.', 1.042, 1.055, 1.006, 1.012, 4.2, 5.6, 8, 20, 2, 5, true),
  ('American Wheat Beer', 'Standard American Beer', 'A pale, refreshing grainy, doughy, or bready wheat beer with a clean fermentation profile and a variable hop character and bitterness. Its lighter body and higher carbonation contribute to its easy-drinking nature.', 1.04, 1.055, 1.008, 1.013, 4, 5.5, 15, 30, 3, 6, true),
  ('International Pale Lager', 'International Lager', 'A highly-attenuated pale lager without strong flavors, typically well-balanced and highly carbonated. Served cold, it is refreshing and thirst-quenching.', 1.042, 1.05, 1.008, 1.012, 4.5, 6, 18, 25, 2, 6, true),
  ('International Amber Lager', 'International Lager', 'A smooth, easily-drinkable, malty amber lager with a flavorful caramel or toast character. Usually fairly well-attenuated, often with an adjunct quality and restrained bitterness.', 1.042, 1.055, 1.008, 1.014, 4.5, 6, 8, 25, 6, 14, true),
  ('International Dark Lager', 'International Lager', 'A darker, richer, and somewhat sweeter version of international pale lager with a little more body and flavor, but equally restrained in bitterness. The low bitterness leaves the malt as the primary flavor element, and the low hop levels provide very little in the way of balance.', 1.044, 1.056, 1.008, 1.012, 4.2, 6, 8, 20, 14, 30, true),
  ('Czech Pale Lager', 'Czech Lager', 'A lighter-bodied, rich, refreshing, hoppy, bitter pale Czech lager having the familiar flavors of the stronger Czech Premium Pale Lager (Pilsner-type) beer but in a lower alcohol, lighter-bodied, and slightly less intense format.', 1.028, 1.044, 1.008, 1.014, 3, 4.1, 20, 35, 3, 6, true),
  ('Czech Premium Pale Lager', 'Czech Lager', 'A refreshing pale Czech lager with considerable malt and hop character and a longfinish. The malt flavors are complex for a Pilsner-type beer.The bitterness is strong and clean butlacks harshness, which gives a well-balanced, roundedflavor impression that enhances drinkability.', 1.044, 1.06, 1.013, 1.017, 4.2, 5.8, 30, 45, 3.5, 6, true),
  ('Czech Amber Lager', 'Czech Lager', 'A malty amber Czech lager with a hop character that can vary from low to quite significant. The malt flavors also can vary, leading to different interpretations and balances ranging from drier, bready, and slightly biscuity to sweeter and somewhat caramel-like.', 1.044, 1.06, 1.013, 1.017, 4.4, 5.8, 20, 35, 10, 16, true),
  ('Czech Dark Lager', 'Czech Lager', 'A rich, dark, malty Czech lager with a roast character that can vary from almost absent to quite prominent. Malty balance and an interesting and complex flavor profile, with variable levels of hopping that provides a range of possible interpretations.', 1.044, 1.06, 1.013, 1.017, 4.4, 5.8, 18, 34, 17, 35, true),
  ('Munich Helles', 'Pale Malty European Lager', 'A gold-colored German lager with a smooth, malty flavor and a soft, dry finish. Subtle spicy, floral, or herbal hops and restrained bitterness help keep the balance malty but not sweet, which helps make this beer a refreshing, everyday drink.', 1.044, 1.048, 1.006, 1.012, 4.7, 5.4, 16, 22, 3, 5, true),
  ('Festbier', 'Pale Malty European Lager', 'A smooth, clean, pale German lager with a moderately strong malty flavor and a light hop character. Deftly balances strength and drinkability, with a palate impression and finish that encourages drinking. Showcases elegant German malt flavors without becoming too heavy or filling.', 1.054, 1.057, 1.01, 1.012, 5.8, 6.3, 18, 25, 4, 6, true),
  ('Helles Bock', 'Pale Malty European Lager', 'A relatively pale, strong, malty German lager with a nicely attenuated finish that enhances drinkability. The hop character is generally more apparent and the malt character less deeply rich than in other Bocks.', 1.064, 1.072, 1.011, 1.018, 6.3, 7.4, 23, 35, 6, 9, true),
  ('German Leichtbier', 'Pale Bitter European Beer', 'A pale, highly-attenuated, light-bodied German lager with lower alcohol and calories than standard-strength beers. Moderately bitter with noticeable malt and hop flavors, the beer is still interesting to drink.', 1.026, 1.034, 1.006, 1.01, 2.4, 3.6, 15, 28, 1.5, 4, true),
  ('Kölsch', 'Pale Bitter European Beer', 'A subtle, brilliantly clear, pale beer with a delicate balance of malt, fruit, and hop character, moderate bitterness, and a well-attenuated but soft finish. Freshness makes a huge difference with this beer, as the delicate character can fade quickly with age.', 1.044, 1.05, 1.007, 1.011, 4.4, 5.2, 18, 30, 3.5, 5, true),
  ('German Helles Exportbier', 'Pale Bitter European Beer', 'A goldenGerman lager balancing a smooth malty profile with a bitter, hoppy character in a slightly above-average body and strength beer.', 1.05, 1.058, 1.008, 1.015, 5, 6, 20, 30, 4, 6, true),
  ('German Pils', 'Pale Bitter European Beer', 'A pale, dry, bitter German lagerfeaturing a prominent hop aroma. Crisp, clean, and refreshing, showing a brilliant gold color with excellent head retention.', 1.044, 1.05, 1.008, 1.013, 4.4, 5.2, 22, 40, 2, 4, true),
  ('Märzen', 'Amber Malty European Lager', 'An amber,malty German lager with a clean, rich, toasty, bready malt flavor, restrained bitterness, and a well-attenuated finish. The overall malt impression is soft, elegant, and complex, with a rich malty aftertaste that is never cloying or heavy.', 1.054, 1.06, 1.01, 1.014, 5.6, 6.3, 18, 24, 8, 17, true),
  ('Rauchbier', 'Amber Malty European Lager', 'Abeechwood-smoked,malty,amber German lager. The expected Märzen profile of toasty-rich malt, restrained bitterness, clean fermentation, and a relatively dry finish is enhanced by anoticeable to intense smoke character.', 1.05, 1.057, 1.012, 1.016, 4.8, 6, 20, 30, 12, 22, true),
  ('Dunkles Bock', 'Amber Malty European Lager', 'A strong,dark, malty German lager beer that emphasizes the malty-rich and somewhat toasty qualities of continental malts without being sweet in the finish.', 1.064, 1.072, 1.013, 1.019, 6.3, 7.2, 20, 27, 14, 22, true),
  ('Vienna Lager', 'Amber Bitter European Beer', 'A moderate-strength continental amber lager with a soft, smooth maltiness and a balanced, moderate bitterness, yet finishing relatively dry. The malt flavor is clean, bready-rich, and somewhat toasty, with an elegant impression derived from quality base malts and process, not specialty malts or adjuncts.', 1.048, 1.055, 1.01, 1.014, 4.7, 5.5, 18, 30, 9, 15, true),
  ('Altbier', 'Amber Bitter European Beer', 'A moderately colored, well-attenuated, bitter beer with a rich maltiness balancing a strong bitterness. Light and spicy hop character complements the malt. A dry beer with a firm body and smooth palate.', 1.044, 1.052, 1.008, 1.014, 4.3, 5.5, 25, 50, 9, 17, true),
  ('Munich Dunkel', 'Dark European Lager', 'A traditional malty brown lager from Bavaria. Deeply toasted, bready malt flavors without any roasty or burnt flavors. Smooth and rich, with a restrained bitterness and a relatively dry finish that allows for drinking in quantity.', 1.048, 1.056, 1.01, 1.016, 4.5, 5.6, 18, 28, 17, 28, true),
  ('Schwarzbier', 'Dark European Lager', 'A dark German lager that balances roasted yet smooth malt flavors with moderate hop bitterness. The lighter body, dryness, and lack of a harsh, burnt, or heavy aftertaste helps make this beer quite drinkable.', 1.046, 1.052, 1.01, 1.016, 4.4, 5.4, 20, 35, 19, 30, true),
  ('Doppelbock', 'Strong European Beer', 'A strong, rich, and very malty German lager that can have both pale and dark variants. The darker versions have more richly-developed, deeper malt flavors, while the paler versions have slightly more hops and dryness.', 1.072, 1.112, 1.016, 1.024, 7, 10, 16, 26, 6, 25, true),
  ('Eisbock', 'Strong European Beer', 'A strong, full-bodied, rich, and malty dark German lager often with a viscous quality and strong flavors. Even though flavors are concentrated, the alcohol should be smooth and warming, not burning.', 1.078, 1.12, 1.02, 1.035, 9, 14, 25, 35, 17, 30, true),
  ('Baltic Porter', 'Strong European Beer', 'A strong, dark, malty beer with differentinterpretationswithin the Baltic region. Smooth, warming, and richly malty, with complex dark fruit flavors and a roasted flavor without burnt notes.', 1.06, 1.09, 1.016, 1.024, 6.5, 9.5, 20, 40, 17, 30, true),
  ('Weissbier', 'German Wheat Beer', 'A pale, refreshing, lightly-hopped German wheat beer with high carbonation, dry finish, fluffy mouthfeel, and a distinctive banana-and-clove weizen yeast fermentation profile.', 1.044, 1.053, 1.008, 1.014, 4.3, 5.6, 8, 15, 2, 6, true),
  ('Dunkles Weissbier', 'German Wheat Beer', 'A moderatelydark German wheat beer with a distinctive banana-and-clove weizen yeast fermentation profile, supported by a toasted bread or caramel malt flavor. Highly carbonated and refreshing, with a creamy, fluffy texture and light finish.', 1.044, 1.057, 1.008, 1.014, 4.3, 5.6, 10, 18, 14, 23, true),
  ('Weizenbock', 'German Wheat Beer', 'A strong and malty Germanwheat beer combining the best wheat and yeast flavors of a Weissbier with the rich maltiness, strength, and body of a Bock. The style range includes Bock and Doppelbock strength, with variations for pale and dark color.', 1.064, 1.09, 1.015, 1.022, 6.5, 9, 15, 30, 6, 25, true),
  ('Ordinary Bitter', 'British Bitter', 'Low gravity, alcohol, and carbonation make this an easy-drinking session beer. The malt profile can vary in flavor and intensity, but should never override the overall bitter impression. Drinkability is a critical component of the style.', 1.03, 1.039, 1.007, 1.011, 3.2, 3.8, 25, 35, 8, 14, true),
  ('Best Bitter', 'British Bitter', 'A flavorful, yet refreshing, session beer. Some examples can be more malt balanced, but this should not override the overall bitter impression. Drinkability is a critical component of the style.', 1.04, 1.048, 1.008, 1.012, 3.8, 4.6, 25, 40, 8, 16, true),
  ('Strong Bitter', 'British Bitter', 'An average-strength to moderately-strong British bitter ale. The balance may vary between fairly even between malt and hops to somewhat bitter. Drinkability is a critical component of the style. A rather broad style that allows for considerable interpretation by the brewer.', 1.048, 1.06, 1.01, 1.016, 4.6, 6.2, 30, 50, 8, 18, true),
  ('British Golden Ale', 'Pale Commonwealth Beer', 'A hop-forward, average-strength to moderately-strong pale bitter. Drinkability and a refreshing quality are critical components of the style, as it was initially a summer seasonal beer.', 1.038, 1.053, 1.006, 1.012, 3.8, 5, 20, 45, 2, 5, true),
  ('Australian Sparkling Ale', 'Pale Commonwealth Beer', 'A well-balanced, pale, highly-carbonated, and refreshing ale suitable for drinking in a hot climate. Fairly bitter, with a moderate herbal-spicy hop and pome fruit ester profile. Smooth, neutral malt flavors with a fuller body but a crisp, highly-attenuated finish.', 1.038, 1.05, 1.004, 1.006, 4.5, 6, 20, 35, 4, 7, true),
  ('English IPA', 'Pale Commonwealth Beer', 'A bitter, moderately-strong, very well-attenuated pale British ale with a dry finish and a hoppy aroma and flavor. Classic British ingredients provide the most authentic flavor profile.', 1.05, 1.07, 1.01, 1.015, 5, 7.5, 40, 60, 6, 14, true),
  ('Dark Mild', 'Brown British Beer', 'A dark, low-gravity, malt-focused British session ale readily suited to drinking in quantity. Refreshing, yet flavorful for its strength, with a wide range of dark malt or dark sugar expression.', 1.03, 1.038, 1.008, 1.013, 3, 3.8, 10, 25, 14, 25, true),
  ('British Brown Ale', 'Brown British Beer', 'A malty, caramelly,brown British ale without the roasted flavors of a Porter. Balanced and flavorful, but usually a little stronger than most average UK beers.', 1.04, 1.052, 1.008, 1.013, 4.2, 5.9, 20, 30, 12, 22, true),
  ('English Porter', 'Brown British Beer', 'A moderate-strength dark brown English ale with a restrained roasty, bitter character. May have a range of roasted flavors, generally without burnt qualities, and often has a malty chocolate and caramelprofile.', 1.04, 1.052, 1.008, 1.014, 4, 5.4, 18, 35, 20, 30, true),
  ('Scottish Light', 'Scottish Ale', 'A low-alcohol, maltybeer with lightcaramel, toast, toffee, and fruit flavors. A slight roast dryness offsets the residual sweetness in the finish, with the bitterness perceived only to keep the beer from being cloying.', 1.03, 1.035, 1.01, 1.013, 2.5, 3.3, 10, 20, 17, 25, true),
  ('Scottish Heavy', 'Scottish Ale', 'A lower-alcohol, maltybeer with lightcaramel, toast, toffee, and fruity flavors. A slight roast dryness offsets the residual sweetness in the finish, with the bitterness perceived only to keep the beer from being cloying.', 1.035, 1.04, 1.01, 1.015, 3.3, 3.9, 10, 20, 12, 20, true),
  ('Scottish Export', 'Scottish Ale', 'A moderate-strength, maltybeer with light caramel, toast, toffee, and fruit flavors. A slight roast dryness offsets the residual sweetness in the finish, with the bitterness perceived only to keep the beer from being cloying.', 1.04, 1.06, 1.01, 1.016, 3.9, 6, 15, 30, 12, 20, true),
  ('Irish Red Ale', 'Irish Beer', 'An easy-drinking pint, often with subtle flavors. Slightly malty in the balance sometimes with an initial soft toffee or caramel sweetness, a slightly grainy-biscuity palate, and a touch of roasted dryness in the finish. Some versions can emphasize the caramel and sweetness more, while others will favor the grainy palate and roasted dryness.', 1.036, 1.046, 1.01, 1.014, 3.8, 5, 18, 28, 9, 14, true),
  ('Irish Stout', 'Irish Beer', 'A black beer with a pronounced roasted flavor, often similar to coffee. The balance can range from fairly even to quite bitter, with the more balanced versions having a little malty sweetness and the bitter versions being quite dry. Draught versions typically are creamy from a nitro pour, but bottled versions will not have this dispense-derived character. The roasted flavor can range from dry and coffee-like to somewhat chocolaty.', 1.036, 1.044, 1.007, 1.011, 3.8, 5, 25, 45, 25, 40, true),
  ('Irish Extra Stout', 'Irish Beer', 'A fuller-bodied black beer with a pronounced roasted flavor, often similar to coffee and dark chocolate with some malty complexity. The balance can range from moderately bittersweet to bitter, with the more balanced versions having up to moderate malty richness and the bitter versions being quite dry.', 1.052, 1.062, 1.01, 1.014, 5, 6.5, 35, 50, 30, 40, true),
  ('Sweet Stout', 'Dark British Beer', 'A very dark, sweet, full-bodied, slightly roasty stout that can suggest coffee-and-cream, or sweetened espresso.', 1.044, 1.06, 1.012, 1.024, 4, 6, 20, 40, 30, 40, true),
  ('Oatmeal Stout', 'Dark British Beer', 'A dark, roasty, full-bodied stout with enough sweetness to support the oat backbone.The sweetness, balance, and oatmeal impression can vary considerably.', 1.045, 1.065, 1.01, 1.018, 4.2, 5.9, 25, 40, 22, 40, true),
  ('Tropical Stout', 'Dark British Beer', 'A very dark, sweet, fruity, moderately strong stout with smooth, roasty flavors,yet no burnt harshness.', 1.056, 1.075, 1.01, 1.018, 5.5, 8, 30, 50, 30, 40, true),
  ('Foreign Extra Stout', 'Dark British Beer', 'A very dark, rich, moderately strong, fairly dry stout with prominent roast flavors.', 1.056, 1.075, 1.01, 1.018, 6.3, 8, 50, 70, 30, 40, true),
  ('British Strong Ale', 'Strong British Ale', 'An ale of respectable alcoholic strength, traditionally bottled-conditioned and cellared. Can have a wide range of interpretations, but most will have varying degrees of malty richness, late hops and bitterness, fruity esters, and alcohol warmth. The malt and adjunct flavors and intensity can vary widely, but any combination should result in an agreeable palate experience.', 1.055, 1.08, 1.015, 1.022, 5.5, 8, 30, 60, 8, 22, true),
  ('Old Ale', 'Strong British Ale', 'A stronger-than-averageEnglish ale, though usually not as strong or rich as an English Barley Wine, but usually malty. Warming. Shows positive maturation effects of a well-kept, aged beer.', 1.055, 1.088, 1.015, 1.022, 5.5, 9, 30, 60, 10, 22, true),
  ('Wee Heavy', 'Strong British Ale', 'Rich, sweet malt depth with caramel, toffee, and fruity flavors. Full-bodied and chewy, with warming alcohol. Restrained bitterness, but not cloying or syrupy.', 1.07, 1.13, 1.018, 1.04, 6.5, 10, 17, 35, 14, 25, true),
  ('English Barley Wine', 'Strong British Ale', 'A strong and richly malty ale witha pleasant fruity or hoppy depth. A wintertime sipper with a full, chewy body and warming alcohol.', 1.08, 1.12, 1.018, 1.03, 8, 12, 35, 70, 8, 22, true),
  ('Blonde Ale', 'Pale American Ale', 'Easy-drinking, approachable, malt-oriented American craft beer, often with interesting fruit, hop, or character malt notes. Well-balanced and clean, is a refreshing pint without aggressive flavors.', 1.038, 1.054, 1.008, 1.013, 3.8, 5.5, 15, 28, 3, 6, true),
  ('American Pale Ale', 'Pale American Ale', 'An average-strength, hop-forward, pale American craft beer with sufficient supporting malt to make the beer balanced and drinkable. The clean hop presence can reflect classic or modern American or New World hop varieties with a wide range of characteristics.', 1.045, 1.06, 1.01, 1.015, 4.5, 6.2, 30, 50, 5, 10, true),
  ('American Amber Ale', 'Amber and Brown American Beer', 'An amber, hoppy, moderate-strength American craft beer with a malty caramel flavor. The balance can vary quite a bit, with some versions being fairly malty and others being aggressively hoppy. Hoppy and bitter versions should not have clashing flavors with the caramel malt profile.', 1.045, 1.06, 1.01, 1.015, 4.5, 6.2, 25, 40, 10, 17, true),
  ('California Common', 'Amber and Brown American Beer', 'A toasty and caramelly, fairly bitter, standard-strength beer with an interesting fruitiness and rustic, woody hop character. Smooth and well carbonated.', 1.048, 1.054, 1.011, 1.014, 4.5, 5.5, 30, 45, 9, 14, true),
  ('American Brown Ale', 'Amber and Brown American Beer', 'A malty but hoppy standard-strength American ale frequently with chocolate and caramel flavors. The hop flavor and aroma complement and enhance the malt rather than clashing with it.', 1.045, 1.06, 1.01, 1.016, 4.3, 6.2, 20, 30, 18, 35, true),
  ('American Porter', 'American Porter and Stout', 'A malty, bitter, and often somewhat hoppydark beer with a balanced,roasted, and frequently chocolatey character.', 1.05, 1.07, 1.012, 1.018, 4.8, 6.5, 25, 50, 22, 40, true),
  ('American Stout', 'American Porter and Stout', 'A fairly strong, highly roasted, bitter, hoppy dark stout. The body and dark flavors typical of stouts with a more aggressive American hop character and bitterness.', 1.05, 1.075, 1.01, 1.022, 5, 7, 35, 75, 30, 40, true),
  ('Imperial Stout', 'American Porter and Stout', 'An intensely-flavored, very strong, very dark stout with a broad range of interpretations. Roasty-burnt malt with a depth of dark or dried fruit flavors, and a warming, bittersweet finish. Despite the intense flavors, the components need to meld together to create a complex, harmonious beer, not a hot mess – sometimes only accomplished with age.', 1.075, 1.115, 1.018, 1.03, 8, 12, 50, 90, 30, 40, true),
  ('American IPA', 'IPA', 'A decidedly hoppy and bitter, moderately strong,pale American ale. The balance is hop-forward, with a clean fermentation profile, dryish finish, and clean, supporting malt allowing a creative range of hop character to shine through.', 1.056, 1.07, 1.008, 1.014, 5.5, 7.5, 40, 70, 6, 14, true),
  ('Specialty IPA', 'IPA', 'A beer with the dryness, hop-forward balance, and flavor characteristics of an American IPA, but darker in color. Darker malts add a gentle and supportive flavor, not a strongly roasted or burnt character.', 1.05, 1.085, 1.01, 1.018, 5.5, 9, 50, 90, 25, 40, true),
  ('Hazy IPA', 'IPA', 'An American IPA with intense fruit flavors and aromas, a soft body, smooth mouthfeel, and often opaque with substantial haze. Less perceived bitterness than traditional IPAs but always massively hop-forward.', 1.06, 1.085, 1.01, 1.015, 6, 9, 25, 60, 3, 7, true),
  ('Double IPA', 'Strong American Ale', 'An intensely hoppy, fairly strong, bitter pale ale without the big, rich, complex maltiness, residual sweetness, and body of an American Barleywine. Strongly hopped, but clean, dry, and lacking harshness. Despite showing its strength, drinkability is an important consideration.', 1.065, 1.085, 1.008, 1.018, 7.5, 10, 60, 100, 6, 14, true),
  ('American Strong Ale', 'Strong American Ale', 'A malty, bitter, and strong American Ale fitting in the space between American Barleywine, Double IPA, and Red IPA. The malty and hoppy flavors can be quite strong, but are generally in balance.', 1.062, 1.09, 1.014, 1.024, 6.3, 10, 50, 100, 7, 18, true),
  ('American Barleywine', 'Strong American Ale', 'A very strong, malty, hoppy, bitter American ale with a rich palate, full mouthfeel, and warming aftertaste, suitable for contemplative sipping.', 1.08, 1.12, 1.016, 1.03, 8, 12, 50, 100, 9, 18, true),
  ('Wheatwine', 'Strong American Ale', 'A richly textured, high alcohol sipping beer with a significant grainy, bready flavor, and a sleek body. The emphasis is first on the bready, wheaty flavors with malt, hops, fruity yeast, and alcohol complexity.', 1.08, 1.12, 1.016, 1.03, 8, 12, 30, 60, 6, 14, true),
  ('Berliner Weisse', 'European Sour Ale', 'A very pale, refreshing, low-alcohol German wheat beer with a clean lactic sourness and a very high carbonation level. A light bread dough malt flavor supports the sourness, which shouldn’t seem artificial. A gentle fruitiness is found in the best examples.', 1.028, 1.032, 1.003, 1.006, 2.8, 3.8, 3, 8, 2, 3, true),
  ('Flanders Red Ale', 'European Sour Ale', 'A sour and fruityoak-aged reddish-brown Belgian-style ale with supportive toasty malt flavors and fruit complexity. The dry, tannic finish supports the suggestion of a vintage red wine.', 1.048, 1.057, 1.002, 1.012, 4.6, 6.5, 10, 25, 10, 17, true),
  ('Oud Bruin', 'European Sour Ale', 'A malty, fruity, aged, somewhat sour Belgian-style brown ale with a caramel-chocolate malt flavor, and often substantial alcohol.', 1.04, 1.074, 1.008, 1.012, 4, 8, 20, 25, 17, 22, true),
  ('Lambic', 'European Sour Ale', 'A fairly sour, often moderately funky, wild Belgian wheat beer with sourness taking the place of hop bitterness in the balance. Traditionally served uncarbonated as a café drink.', 1.04, 1.054, 1.001, 1.01, 5, 6.5, 0, 10, 3, 6, true),
  ('Gueuze', 'European Sour Ale', 'A very refreshing, highly carbonated, pleasantly sour but balanced wild Belgian wheat beer. The wild beer character can be complex and varied, combining sour, funky, and fruity flavors.', 1.04, 1.054, 1, 1.006, 5, 8, 0, 10, 5, 6, true),
  ('Fruit Lambic', 'European Sour Ale', 'A complex, refreshing, pleasantly sour Belgian wheat beerblending a complementary fermented fruit character with a sour, funky Gueuze.', 1.04, 1.06, 1, 1.01, 5, 7, 0, 10, 3, 7, true),
  ('Gose', 'European Sour Ale', 'A tart, lightly-bittered historical central European wheat beer with a distinctive but restrained salt and coriander character. Very refreshing, with a dry finish,high carbonation, and bright flavors.Aroma', 1.036, 1.056, 1.006, 1.01, 4.2, 4.8, 5, 12, 3, 4, true),
  ('Witbier', 'Belgian Ale', 'A pale, hazy Belgian wheat beer with spices accentuating the yeast character. Adelicate, lightly spiced, moderate-strength ale that is a refreshing summer drink with its high carbonation, dry finish, and light hopping.', 1.044, 1.052, 1.008, 1.012, 4.5, 5.5, 8, 20, 2, 4, true),
  ('Belgian Pale Ale', 'Belgian Ale', 'A top-fermented, all malt, average strength Belgian ale that is moderately bitter, not dry-hopped, and without strong flavors. The copper-colored beer lacks the aggressive yeast character or sourness of many Belgian beers, buthas a well-balanced, malty, fruity, and often bready and toasty profile.', 1.048, 1.054, 1.01, 1.014, 4.8, 5.5, 20, 30, 8, 14, true),
  ('Bière de Garde', 'Belgian Ale', 'A family of smooth, fairly strong, malty, lagered artisanal French beer with a range of malt flavors appropriate for the blond, amber, or brown color. All are malty yet dry, with clean flavors.Darker versions have more malt character, while paler versions can have more hops while still remaining malt-focused beers.', 1.06, 1.08, 1.008, 1.016, 6, 8.5, 18, 28, 6, 19, true),
  ('Belgian Blond Ale', 'Strong Belgian Ale', 'A golden,moderately-strong Belgian ale with a pleasantly subtlecitrusy-spicy yeast complexity, smooth malty palate, and dry, soft finish.', 1.062, 1.075, 1.008, 1.018, 6, 7.5, 15, 30, 4, 6, true),
  ('Saison', 'Strong Belgian Ale', 'A family of refreshing, highly attenuated, hoppy, and fairly bitter Belgian ales with a very dry finish and high carbonation. Characterized by a fruity, spicy, sometimes phenolic fermentation profile,and the use of cereal grains and sometimes spices for complexity. Several variations in strength and color exist.', 1.048, 1.065, 1.002, 1.008, 5, 7, 20, 35, 5, 14, true),
  ('Belgian Golden Strong Ale', 'Strong Belgian Ale', 'A very pale, highly attenuated, strong Belgian ale that is more fruity and hoppy than spicy. Complex and delicate, the dry finish, light body, and high carbonationaccentuate the yeast and hop character.Sparkling carbonation and effervescent, forming a rocky white head.', 1.07, 1.095, 1.005, 1.016, 7.5, 10.5, 22, 35, 3, 6, true),
  ('Belgian Single', 'Monastic Ale', 'A blond, bitter, hoppy table beer that is very dry and highly carbonated. The aggressive fruity-spicy Belgian yeast character and high bitterness is forward in the balance, with a soft, supportive grainy-sweet malt palate, and a spicy-floral hop profile.', 1.044, 1.054, 1.004, 1.01, 4.8, 6, 25, 45, 3, 5, true),
  ('Belgian Dubbel', 'Monastic Ale', 'A deep reddish-copper, moderately strong, malty, complex Belgian ale with rich malty flavors, dark or dried fruit esters, and light alcohol blended together in a malty presentation that still finishes fairly dry.', 1.062, 1.075, 1.008, 1.018, 6, 7.6, 15, 25, 10, 17, true),
  ('Belgian Tripel', 'Monastic Ale', 'A strong,pale, somewhat spicy Belgian ale with a pleasant rounded malt flavor, firm bitterness, and dry finish. Quite aromatic, with spicy, fruity, and light alcohol notes combining with the supportive clean malt character to produce a surprisingly drinkable beverage considering the high alcohol content.', 1.075, 1.085, 1.008, 1.014, 7.5, 9.5, 20, 40, 4.5, 7, true),
  ('Belgian Dark Strong Ale', 'Monastic Ale', 'A dark, complex, very strong Belgian ale with a delicious blend of malt richness, dark fruit flavors, and spicy notes. Complex, rich, smooth, and dangerous.', 1.075, 1.11, 1.01, 1.024, 8, 12, 20, 35, 12, 22, true),
  ('Brett Beer', 'American Wild Ale', 'Most often drier and fruitier than the base style suggests. Fruity or funky notes range from low to high, depending on the age of the beer and strains of Brett used. May possess a light non-lactic acidity.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
