  ('Fruit Beer', 'Fruit Beer', 'A pleasant integration of fruit with beer, but still recognizable as beer. The fruit character should be evident but in balance with the beer, not so forward as to suggest an artificial product.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
  ('Fruit and Spice Beer', 'Fruit Beer', 'A tasteful union of fruit, spice, and beer, but still recognizable as beer. The fruit and spice character should each be evident but in balance with the beer, not so forward as to suggest an artificial product.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true),
